def course(day):
 b=BOOKS[day];assigned=[SLIDES[n-1] for n in b['slides']]
 quiz=QUIZ[day]
 cards=list(dict.fromkeys([(s[4],s[5]) for s in assigned if s[0]<18]+[(q,w) for q,o,r,w in quiz]))
 return dict(titel=b['title'],unter=f'Lektion 15 · Werkstattreihe {day-15}/3',datum=b['date'],folien=SOURCE_FILE,folie_start=min(b['slides']),kurz=b['subtitle'],lernheft=b['pdf'],learnings=[dict(id=f'l{i}',folie=s[0],satz=s[1],erklaert=s[2]) for i,s in enumerate(assigned,1)],karten=cards,test=[dict(frage=q,optionen=opts,richtig=r,warum=why) for q,opts,r,why in quiz],begriffe=[('MCP','Standardisierte Schnittstelle zu Werkzeug- und Datendiensten.'),('Client','Die Anwendung, die eine Verbindung benutzt.'),('Server','Der Dienst oder Prozess, der Werkzeuge anbietet.'),('Transport','Technischer Weg der Kommunikation, etwa HTTP oder stdio.'),('OAuth','Anmeldung und Freigabe für den Zugriff auf einen Dienst.'),('Kontext','Material, das in der aktuellen Arbeit berücksichtigt werden kann.'),('Skill','Wiederverwendbare Anleitung mit optionalen Ressourcen.'),('Memory','Gespeicherter Kontext; kein verlässlicher Ersatz für aktuelle Quellen.'),('Hook','Ein Handgriff, der bei einem definierten Ereignis ausgelöst wird.'),('Worktree','Getrennter Arbeitsstand eines Git-Projekts.'),('Referenz','Benannte Vergleichsquelle für eine Prüfung.'),('Nullbasis','Eine Bezugsgröße von null; gewöhnliche prozentuale Änderung ist dann nicht definiert.')])
